import { Project } from "../domain/project";
import { ProjectRepository, TaskFilter, TaskRepository, UserRepository } from "../domain/repositories";
import { Task, TaskStatus, taskStatuses } from "../domain/task";
import { User } from "../domain/user";

export interface CreateProjectInput { name: string; }
export interface CreateUserInput { name: string; }
export interface CreateTaskInput {
  title: string;
  description: string;
  dueDate?: string;
  status?: TaskStatus;
  assigneeId?: string;
}
export interface ListTasksInput { status?: TaskStatus; assigneeId?: string; }
export interface TaskDto {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: string;
  status: TaskStatus;
  assigneeId?: string;
}

export class ResourceNotFoundError extends Error {
  public constructor(resource: string, id: string) {
    super(`${resource} ${id} was not found`);
    this.name = "ResourceNotFoundError";
  }
}

export class InvalidInputError extends Error {
  public constructor(message: string) {
    super(message);
    this.name = "InvalidInputError";
  }
}

export class TaskService {
  public constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
    private readonly createId: () => string,
  ) {}

  public createProject(input: CreateProjectInput): { id: string; name: string } {
    this.requireText(input.name, "Project name");
    const project = new Project(this.createId(), input.name.trim());
    this.projects.save(project);
    return project;
  }

  public createUser(input: CreateUserInput): { id: string; name: string } {
    this.requireText(input.name, "User name");
    const user = new User(this.createId(), input.name.trim());
    this.users.save(user);
    return user;
  }

  public createTask(projectId: string, input: CreateTaskInput): TaskDto {
    this.getProject(projectId);
    this.requireText(input.title, "Task title");
    this.requireText(input.description, "Task description");
    if (input.assigneeId !== undefined && !this.users.existsById(input.assigneeId)) {
      throw new ResourceNotFoundError("User", input.assigneeId);
    }
    const dueDate = this.parseDueDate(input.dueDate);
    const status = input.status ?? "todo";
    if (!taskStatuses.includes(status)) {
      throw new InvalidInputError("Task status is invalid");
    }
    const task = new Task(this.createId(), projectId, input.title.trim(), input.description.trim(), dueDate, input.assigneeId, status);
    this.tasks.save(task);
    return this.toDto(task);
  }

  public listProjectTasks(projectId: string, filter: ListTasksInput): TaskDto[] {
    this.getProject(projectId);
    if (filter.status !== undefined && !taskStatuses.includes(filter.status)) {
      throw new InvalidInputError("Task status is invalid");
    }
    const taskFilter: TaskFilter = filter;
    return this.tasks.findByProjectId(projectId, taskFilter).map((task) => this.toDto(task));
  }

  public markTaskDone(taskId: string): TaskDto {
    const task = this.tasks.findById(taskId);
    if (task === undefined) {
      throw new ResourceNotFoundError("Task", taskId);
    }
    task.markDone();
    this.tasks.save(task);
    return this.toDto(task);
  }

  private getProject(id: string): Project {
    const project = this.projects.findById(id);
    if (project === undefined) throw new ResourceNotFoundError("Project", id);
    return project;
  }

  private requireText(value: string, label: string): void {
    if (typeof value !== "string" || value.trim().length === 0) throw new InvalidInputError(`${label} is required`);
  }

  private parseDueDate(value: string | undefined): Date | undefined {
    if (value === undefined) return undefined;
    const dueDate = new Date(value);
    if (Number.isNaN(dueDate.getTime())) throw new InvalidInputError("Due date is invalid");
    return dueDate;
  }

  private toDto(task: Task): TaskDto {
    return { id: task.id, projectId: task.projectId, title: task.title, description: task.description, dueDate: task.dueDate?.toISOString(), status: task.status, assigneeId: task.assigneeId };
  }
}

